      ("Жемқорлық қай конституциялық қағиданы бұзады?", ["Заң алдындағы теңдікті", "Тіл туралы ережені", "Рәміздерді", "Аумақты"], 0),
      ("Құқығың бұзылса, бірінші не істейсің?", ["Төбелесемін", "Сабырмен тоқтатуды талап етіп, ересекке айтамын", "Үндемеймін", "Кек аламын"], 1),
